/// Whether an entry id is safe to turn into a filename.
///
/// Deliberately a whitelist. Ids are minted by the producer as timestamp-and-counter strings, so
/// this rejects everything a real id never contains.
pub fn is_safe_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 128
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}
